package com.yeyamo_mobile.api.partner_service.interfaces.rest;import static com.yeyamo_mobile.api.partner_service.interfaces.rest.ArtisanDtos.*;import com.yeyamo_mobile.api.partner_service.application.ArtisanProfileService;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/admin/artisans")@PreAuthorize("hasAnyRole('ADMIN','SUPER_ADMIN')")public class AdminArtisanController{private final ArtisanProfileService service;public AdminArtisanController(ArtisanProfileService s){service=s;}@PatchMapping("/{id}/verification")public Response verify(@PathVariable UUID id,@RequestBody@Valid VerificationRequest r,Authentication actor,@RequestHeader(value="X-Correlation-ID",required=false)String c){return service.verify(id,r,actor.getName(),c);}}
